    .query(RowParser.builder<User>()
        .field(PgTypes.int4, User::id)           // id: correct
        .field(PgTypes.text, User::name)         // name: correct
        .field(PgTypes.int4, User::createdAt)    // created_at: WRONG! Should be timestamptz
